import{R as e,S as t,x as n}from"./vue-Bp4HY3mp.js";import{n as r}from"./app-DrdKnICy.js";var i=JSON.parse(`{"path":"/english/vocabulary/physical-geography/landforms/","title":"CH1.6 地貌与地形描述 | 英语","lang":"zh-CN","frontmatter":{"title":"CH1.6 地貌与地形描述","createTime":"2026-11-18T09:50:00.000Z","permalink":"/english/vocabulary/physical-geography/landforms/"},"readingTime":{"minutes":29.85,"words":8955},"git":{"createdTime":1795010783000},"filePathRelative":"english/vocabulary/physical-geography/6.landforms.md","headers":[],"bulletin":false}`),a={name:`6.landforms.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<div class="vocab-card"><h2 id="plain" tabindex="-1"><a class="header-anchor" href="#plain"><span>Plain</span></a></h2><p class="vc-meta"><strong>/pleɪn/</strong> · noun · 名词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：平原</li><li>形容词：简单的，朴素的；明显的；相貌平平的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a coastal plain</td><td>沿海平原</td></tr><tr><td>the Great Plains</td><td>北美大平原</td></tr><tr><td>a vast plain</td><td>广袤的平原</td></tr><tr><td>plain water</td><td>白水，清水</td></tr><tr><td>make it plain that</td><td>明确表示</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The cross-section shows a narrow coastal plain rising steeply to a plateau.</p><blockquote><p>该剖面图显示一条狭窄的沿海平原陡然升高为高原。</p></blockquote><p><strong>Writing Task 2</strong> Flooding is most severe on the plains, where rivers slow down and spread sideways.</p><blockquote><p>洪水在平原上最为严重，因为河流到了这里减速并向两侧漫溢。</p></blockquote><p><strong>Speaking</strong> It&#39;s flat, plain farmland for miles — you can see the horizon in every direction.</p><blockquote><p>方圆数英里都是平坦朴素的农田，朝哪个方向都能看到地平线。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>prairie</td><td>大草原</td><td>北美，草本，土壤肥沃</td></tr><tr><td>lowland</td><td>低地</td><td>强调海拔低</td></tr><tr><td>steppe</td><td>干草原</td><td>欧亚，干旱</td></tr><tr><td>savanna</td><td>稀树草原</td><td>热带，干湿季分明</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>planus</em>（平坦的）→ plain / plane / plan</li><li><strong>Family:</strong> plain 平原 / plainly 明显地 / plainness 朴素 / plane 平面 / plateau 高原</li><li><strong>Memory Tip:</strong> planus = 平。plain 作名词是&quot;平地&quot;，作形容词是&quot;平的 → 朴素的 → 显而易见的&quot;一条线。plain 与 plane 是同根双胞胎。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>地名用复数：the Great Plains。</li><li>形容词&quot;明显的&quot;常配 it is plain that…，不要写成 <s>it is plain</s> 单独结尾。</li><li>与 plateau 对比记：plain 低而平，plateau 高而平。</li></ul></div><div class="vocab-card"><h2 id="plateau" tabindex="-1"><a class="header-anchor" href="#plateau"><span>Plateau</span></a></h2><p class="vc-meta"><strong>/ˈplætəʊ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：高原；平稳期，平台期</li><li>动词：趋于平稳，进入平台期</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a high plateau</td><td>高原</td></tr><tr><td>the Tibetan Plateau</td><td>青藏高原</td></tr><tr><td>reach a plateau</td><td>进入平台期</td></tr><tr><td>plateau at</td><td>稳定在（某水平）</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows sales rising sharply and then plateauing after 2020.</p><blockquote><p>该图显示销售额急剧上升，随后在 2020 年后趋于平稳。</p></blockquote><p><strong>Writing Task 2</strong> The Tibetan Plateau acts as a water tower, feeding Asia&#39;s major rivers.</p><blockquote><p>青藏高原如同水塔，为亚洲主要河流供水。</p></blockquote><p><strong>Speaking</strong> After a year of rapid progress, my English kind of plateaued.</p><blockquote><p>快速进步一年之后，我的英语有点停滞不前了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>tableland</td><td>台地</td><td>地理学，顶面平坦的高地</td></tr><tr><td>upland</td><td>高地</td><td>泛指海拔较高地区</td></tr><tr><td>mesa</td><td>方山</td><td>干旱区，小而四壁陡峭</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 法语 <em>plateau</em>（托盘）← 拉丁 <em>plattus</em>（平的）</li><li><strong>Family:</strong> plateau 高原；平台期 / plate 盘子；板块 / platter 大盘</li><li><strong>Memory Tip:</strong> 法语&quot;托盘&quot;→ 顶面平坦的高地。学习曲线里的&quot;平台期&quot;也是这个词，因为曲线变平了。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 plateaus 或 plateaux 均可，英式偏用 plateaux。</li><li>动词变形 plateaued / plateauing。</li><li>与 plain 区分：只差高度——高原 vs 平原。</li></ul></div><div class="vocab-card"><h2 id="oasis" tabindex="-1"><a class="header-anchor" href="#oasis"><span>Oasis</span></a></h2><p class="vc-meta"><strong>/əʊˈeɪsɪs/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>绿洲；（困境中的）慰藉之处，一片安宁之地</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a desert oasis</td><td>沙漠绿洲</td></tr><tr><td>an oasis of calm</td><td>一片宁静之地</td></tr><tr><td>an oasis in the desert</td><td>沙漠中的绿洲</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map marks an oasis where the caravan route crosses the desert.</p><blockquote><p>该地图标出了商队路线穿越沙漠处的一片绿洲。</p></blockquote><p><strong>Writing Task 2</strong> Oases depend on groundwater that is often thousands of years old and not easily renewed.</p><blockquote><p>绿洲依赖的地下水往往已有数千年历史，且不易更新。</p></blockquote><p><strong>Speaking</strong> After six hours in the heat, the hotel pool felt like an oasis.</p><blockquote><p>在高温里待了六个小时后，酒店泳池简直像一片绿洲。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>watering hole</td><td>水源地</td><td>口语，动物或旅人饮水处</td></tr><tr><td>haven</td><td>避风港</td><td>强调安全、庇护</td></tr><tr><td>refuge</td><td>避难处</td><td>强调躲避危险</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊语 <em>oasis</em>，源自埃及语 <em>wḥꜣt</em>（绿洲、沃土）</li><li><strong>Family:</strong> oasis 绿洲 / oases 绿洲（复数）</li><li><strong>Memory Tip:</strong> 复数 oases /əʊˈeɪsiːz/，与 crisis → crises、analysis → analyses 同一套变复数规则。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>复数 oases，不写 <s>oasises</s>。</li><li>元音开头，用 an oasis。</li><li>比喻义 an oasis of calm 很常用，写作里是加分表达。</li></ul></div><div class="vocab-card"><h2 id="peak" tabindex="-1"><a class="header-anchor" href="#peak"><span>Peak</span></a></h2><p class="vc-meta"><strong>/piːk/</strong> · noun · 名词 / verb · 动词 / adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：顶峰，山峰；峰值，最高点</li><li>动词：达到顶峰，达到最高值</li><li>形容词：高峰的（peak hours）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a snow-capped peak</td><td>雪顶山峰</td></tr><tr><td>reach a peak</td><td>达到峰值</td></tr><tr><td>peak season</td><td>旺季</td></tr><tr><td>peak hours</td><td>高峰时段</td></tr><tr><td>peak at</td><td>最高达到</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows demand peaking in July and falling sharply in September.</p><blockquote><p>该图显示需求在七月达到峰值，九月急剧下降。</p></blockquote><p><strong>Writing Task 2</strong> Peak-hour traffic is the main source of urban air pollution in many cities.</p><blockquote><p>在许多城市，高峰时段的车流是城市空气污染的主要来源。</p></blockquote><p><strong>Speaking</strong> We reached the peak at sunrise — the whole valley was under cloud.</p><blockquote><p>日出时我们登上了山顶，整个山谷都在云海之下。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>summit</td><td>山顶</td><td>指最高点，也指峰会</td></tr><tr><td>top</td><td>顶端</td><td>最泛用</td></tr><tr><td>climax</td><td>高潮</td><td>多用于叙事、事件</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 或与 <em>pike</em>（尖头、尖顶）有关 → peak</li><li><strong>Family:</strong> peak 顶峰；峰值 / peaked 有尖顶的 / peaky 面色苍白的 / off-peak 非高峰的</li><li><strong>Memory Tip:</strong> 一个词同时是&quot;山尖&quot;和&quot;曲线尖&quot;。图表题写 peaked at 500 in July，一句话就把峰值、数值、时间都说清了。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>作动词不及物：Sales peaked at 500 units。</li><li>&quot;在……的顶峰&quot;用 at the peak of。</li><li>off-peak 表&quot;非高峰的&quot;，写作里比 <s>not peak</s> 地道。</li></ul></div><div class="vocab-card"><h2 id="mount" tabindex="-1"><a class="header-anchor" href="#mount"><span>Mount</span></a></h2><p class="vc-meta"><strong>/maʊnt/</strong> · verb · 动词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>动词：登上，骑上；增加，上升（mounting）；发起（活动）</li><li>名词：山（用于山名之前，缩写 Mt）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>Mount Everest</td><td>珠穆朗玛峰</td></tr><tr><td>mount a campaign</td><td>发起一场运动</td></tr><tr><td>mounting pressure</td><td>不断增加的压力</td></tr><tr><td>mount up</td><td>累积</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the route to the summit of Mount Kenya.</p><blockquote><p>该地图显示了通往肯尼亚山山顶的路线。</p></blockquote><p><strong>Writing Task 2</strong> Mounting evidence suggests the glacier is retreating faster than models predicted.</p><blockquote><p>越来越多的证据表明，该冰川退缩的速度快于模型预测。</p></blockquote><p><strong>Speaking</strong> Costs are mounting, and we may have to cancel the trip.</p><blockquote><p>费用在不断增加，我们可能得取消这趟行程。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>ascend</td><td>攀登</td><td>正式，强调向上过程</td></tr><tr><td>climb</td><td>爬</td><td>日常，可及物</td></tr><tr><td>rise</td><td>上升</td><td>指数值、水位等</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>mons</em>（山）→ 法语 <em>monter</em>（上升）</li><li><strong>Family:</strong> mount 登上；山 / mountain 山 / amount 数量 / surmount 克服 / mounting 不断增加的</li><li><strong>Memory Tip:</strong> 两个方向记：往上（mount a horse / mount a campaign）与累积（mounting pressure）。作山名时它站在名字前面：Mount Fuji。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>山名格式是 Mount + 名字（Mount Fuji），不写 <s>Fuji Mount</s>。</li><li>mounting 是&quot;不断增加的&quot;，不是&quot;安装中&quot;。</li><li>amount 与 mount 同源但意思完全不同（数量 vs 登上）。</li></ul></div><div class="vocab-card"><h2 id="mountain" tabindex="-1"><a class="header-anchor" href="#mountain"><span>Mountain</span></a></h2><p class="vc-meta"><strong>/ˈmaʊntən/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>山，山岳；（复数）山脉，山区</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a mountain range</td><td>山脉</td></tr><tr><td>mountainous terrain</td><td>山地地形</td></tr><tr><td>mountain climbing</td><td>登山</td></tr><tr><td>a mountain of</td><td>大量的</td></tr><tr><td>mountain region</td><td>山区</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a mountain range running north to south across the region.</p><blockquote><p>该地图显示了贯穿该地区南北走向的一条山脉。</p></blockquote><p><strong>Writing Task 2</strong> Mountain regions supply water to more than half of humanity.</p><blockquote><p>山区为超过一半的人类提供水源。</p></blockquote><p><strong>Speaking</strong> We could see the mountains from our window on clear days.</p><blockquote><p>天晴的时候，从我们窗户就能看见那些山。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>mount</td><td>山</td><td>仅用于山名之前</td></tr><tr><td>peak</td><td>山峰</td><td>指山顶或独立尖峰</td></tr><tr><td>hill</td><td>小山，丘陵</td><td>高度明显更低</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>mont-</em>（山）→ 法语 <em>montaigne</em></li><li><strong>Family:</strong> mountain 山 / mountainous 多山的 / mount 山；登上 / Montana 蒙大拿州（山地）</li><li><strong>Memory Tip:</strong> mountain 通常指 600 米以上，hill 更矮。a mountain of work 是&quot;堆积如山的工作&quot;，语气比 a lot of work 生动。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;多山的&quot;是 mountainous，别写成 <s>mountaneous</s>。</li><li>mountain range 分开写，不加连字符。</li><li>可数：a mountain / the mountains（山区）。</li></ul></div><div class="vocab-card"><h2 id="range" tabindex="-1"><a class="header-anchor" href="#range"><span>Range</span></a></h2><p class="vc-meta"><strong>/reɪndʒ/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：山脉；（变化）范围，幅度；一系列</li><li>动词：（在一定范围内）变化，从……到……</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a mountain range</td><td>山脉</td></tr><tr><td>a wide range of</td><td>种类繁多的</td></tr><tr><td>temperature range</td><td>温度幅度</td></tr><tr><td>range from A to B</td><td>从 A 到 B 不等</td></tr><tr><td>within range</td><td>在范围内</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The chart shows the range of temperatures recorded at each site.</p><blockquote><p>该图表显示了各站点记录到的温度变化幅度。</p></blockquote><p><strong>Writing Task 2</strong> The country offers a wide range of climates, from desert to rainforest.</p><blockquote><p>该国气候类型多样，从荒漠到雨林都有。</p></blockquote><p><strong>Speaking</strong> Prices range from twenty to two hundred pounds.</p><blockquote><p>价格从二十镑到两百镑不等。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>chain</td><td>山链</td><td>指连绵的山系</td></tr><tr><td>scope</td><td>范围</td><td>多指涉及面、权限</td></tr><tr><td>variety</td><td>种类</td><td>强调多样性，非区间</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>range</em>（排成行）← <em>rang</em>（行列）</li><li><strong>Family:</strong> range 山脉；范围 / arrange 安排 / arrangement 安排 / ranger 护林员</li><li><strong>Memory Tip:</strong> 一条&quot;排成行的东西&quot;：mountain range 山脉、a range of products 一系列产品、range from A to B 区间变化。arrange 就是&quot;排列&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>range from A to B 或 range between A and B，两种都对。</li><li>a wide range of 后接复数名词。</li><li>mountain range 中 range 可数：two mountain ranges。</li></ul></div><div class="vocab-card"><h2 id="ridge" tabindex="-1"><a class="header-anchor" href="#ridge"><span>Ridge</span></a></h2><p class="vc-meta"><strong>/rɪdʒ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>山脊，山岭</li><li>脊状隆起；（气象）高压脊</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a mountain ridge</td><td>山脊</td></tr><tr><td>the ridge line</td><td>脊线</td></tr><tr><td>a ridge of high pressure</td><td>高压脊</td></tr><tr><td>along the ridge</td><td>沿着山脊</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a ridge separating the two river valleys.</p><blockquote><p>该地图显示了一条分隔两个河谷的山脊。</p></blockquote><p><strong>Writing Task 2</strong> Walking along an exposed ridge leaves hikers vulnerable to sudden changes in weather.</p><blockquote><p>走在裸露的山脊上，徒步者容易遭遇天气突变。</p></blockquote><p><strong>Speaking</strong> We followed the ridge for hours, with valleys on both sides.</p><blockquote><p>我们沿着山脊走了好几个小时，两边都是山谷。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>crest</td><td>顶脊</td><td>指最高的一条线</td></tr><tr><td>spine</td><td>脊</td><td>比喻用法，形容狭长山系</td></tr><tr><td>hogback</td><td>猪背岭</td><td>地质术语，两侧陡峭</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>hrycg</em>（背脊）</li><li><strong>Family:</strong> ridge 山脊 / ridged 有脊的 / ridge line 脊线 / ridge of high pressure 高压脊</li><li><strong>Memory Tip:</strong> 山脊就是&quot;山的背脊&quot;，与动物的背同词源。气象里的 ridge of high pressure（高压脊）也是这个&quot;脊&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a ridge / several ridges。</li><li>&quot;沿山脊&quot;用 along the ridge。</li><li>别与 edge（边缘）混：ridge 是凸起的脊，edge 是边界线。</li></ul></div><div class="vocab-card"><h2 id="slope" tabindex="-1"><a class="header-anchor" href="#slope"><span>Slope</span></a></h2><p class="vc-meta"><strong>/sləʊp/</strong> · noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>名词：斜坡，坡地；坡度</li><li>动词：倾斜，成斜坡</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a steep slope</td><td>陡坡</td></tr><tr><td>on a slope</td><td>在斜坡上</td></tr><tr><td>slope down</td><td>向下倾斜</td></tr><tr><td>a slope of 30 degrees</td><td>30 度坡度</td></tr><tr><td>the continental slope</td><td>大陆坡</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The cross-section shows a gentle slope rising towards the east.</p><blockquote><p>该剖面图显示一道缓坡向东升高。</p></blockquote><p><strong>Writing Task 2</strong> Crops grown on slopes lose soil far faster than those on flat land.</p><blockquote><p>坡地上种的作物，土壤流失速度远快于平地。</p></blockquote><p><strong>Speaking</strong> The garden slopes down to the river, so it never floods.</p><blockquote><p>花园向河边倾斜，所以从来不积水。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>incline</td><td>斜面</td><td>更书面，也指铁路坡道</td></tr><tr><td>gradient</td><td>坡度</td><td>工程与地理术语，指数值</td></tr><tr><td>hillside</td><td>山坡</td><td>指实体位置，非几何面</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 中古英语 <em>slope</em>，与 <em>aslope</em>（倾斜地）同源，语感上与 <em>slip</em>（滑）相近</li><li><strong>Family:</strong> slope 斜坡 / sloping 倾斜的 / ski slope 滑雪道 / continental slope 大陆坡</li><li><strong>Memory Tip:</strong> 三种用法一次记：斜坡（a steep slope）、坡度（a slope of 30 degrees）、动词（The land slopes east）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;坡度 30 度&quot;说 a slope of 30 degrees 或 a 30-degree slope。</li><li>动词常用 slope down / slope up / slope towards。</li><li>continental slope 是&quot;大陆坡&quot;，地理必考术语。</li></ul></div><div class="vocab-card"><h2 id="valley" tabindex="-1"><a class="header-anchor" href="#valley"><span>Valley</span></a></h2><p class="vc-meta"><strong>/ˈvæli/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>山谷，河谷；（大河流域的）流域</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a river valley</td><td>河谷</td></tr><tr><td>a deep valley</td><td>深谷</td></tr><tr><td>the valley floor</td><td>谷底</td></tr><tr><td>in the valley</td><td>在山谷里</td></tr><tr><td>the Thames Valley</td><td>泰晤士河流域</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a river valley with settlements along both banks.</p><blockquote><p>该地图显示了一个两岸都有聚落的河谷。</p></blockquote><p><strong>Writing Task 2</strong> Valleys collect cold air at night, which raises the risk of frost.</p><blockquote><p>山谷夜间会积聚冷空气，从而增加霜冻风险。</p></blockquote><p><strong>Speaking</strong> The village sits in a valley surrounded by hills.</p><blockquote><p>村子坐落在一个群山环绕的山谷里。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>vale</td><td>谷</td><td>文学化，多用于地名</td></tr><tr><td>gorge</td><td>峡谷</td><td>窄而深，两侧崖壁陡峭</td></tr><tr><td>basin</td><td>盆地</td><td>宽而平，四周高</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古法语 <em>valee</em> ← 拉丁 <em>vallis</em>（谷）</li><li><strong>Family:</strong> valley 山谷 / vale 谷（诗语）/ valley floor 谷底 / valley-side 谷坡</li><li><strong>Memory Tip:</strong> 三个&quot;谷&quot;按形状分：valley（一般河谷）、gorge（窄深峡谷）、basin（宽平盆地）。the valley floor 是&quot;谷底&quot;，剖面图常用。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>可数：a valley / deep valleys。</li><li>&quot;在山谷里&quot;用 in the valley，不用 <s>on</s>。</li><li>拼写 valley 双 l，别写成 <s>vally</s>。</li></ul></div><div class="vocab-card"><h2 id="hillside" tabindex="-1"><a class="header-anchor" href="#hillside"><span>Hillside</span></a></h2><p class="vc-meta"><strong>/ˈhɪlsaɪd/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>山坡，山腰</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>on the hillside</td><td>在山坡上</td></tr><tr><td>terraced hillside</td><td>梯田山坡</td></tr><tr><td>hillside farming</td><td>坡地耕作</td></tr><tr><td>a wooded hillside</td><td>林木覆盖的山坡</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows terraces cut into the hillside for farming.</p><blockquote><p>该地图显示了为耕作而在山坡上开出的梯田。</p></blockquote><p><strong>Writing Task 2</strong> Deforestation on hillsides accelerates soil erosion far downstream.</p><blockquote><p>山坡上的滥伐会加速下游很远处的水土流失。</p></blockquote><p><strong>Speaking</strong> Their house is built into the hillside, so the roof is at road level.</p><blockquote><p>他们的房子嵌在山坡里，所以屋顶和路面齐平。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>slope</td><td>斜坡</td><td>几何面，非具体位置</td></tr><tr><td>mountainside</td><td>山腰</td><td>规模更大，属大山</td></tr><tr><td>escarpment</td><td>陡崖坡</td><td>地质术语，断层形成</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>hill</em>（丘陵）+ <em>side</em>（侧）</li><li><strong>Family:</strong> hillside 山坡 / hill 小山 / hilltop 山顶 / hilly 多丘陵的</li><li><strong>Memory Tip:</strong> 同一个构词法一串：mountainside 山腰、riverside 河边、roadside 路边、seaside 海滨。side 表&quot;某一侧的地带&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 on the hillside。</li><li>terraced hillside（梯田山坡）是写作高分搭配。</li><li>hillside 指具体位置，slope 指几何坡度，别互替。</li></ul></div><div class="vocab-card"><h2 id="overlook" tabindex="-1"><a class="header-anchor" href="#overlook"><span>Overlook</span></a></h2><p class="vc-meta"><strong>/ˌəʊvəˈlʊk/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>俯瞰，眺望</li><li>忽视，忽略；不予追究</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>overlook the valley</td><td>俯瞰山谷</td></tr><tr><td>overlook a mistake</td><td>忽略一个错误</td></tr><tr><td>be easily overlooked</td><td>容易被忽视</td></tr><tr><td>overlook the fact that</td><td>忽视……这一事实</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a viewpoint that overlooks the whole estuary.</p><blockquote><p>该地图标出了一处可俯瞰整个河口的观景点。</p></blockquote><p><strong>Writing Task 2</strong> Policymakers often overlook the role of traditional knowledge in climate adaptation.</p><blockquote><p>决策者常常忽视传统知识在气候适应中的作用。</p></blockquote><p><strong>Speaking</strong> Our room overlooks the harbour, so we wake up to boats.</p><blockquote><p>我们的房间正对港口，一醒来就能看到船。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>command a view of</td><td>俯瞰</td><td>更书面，强调视野开阔</td></tr><tr><td>ignore</td><td>忽视</td><td>故意不理，主观性强</td></tr><tr><td>neglect</td><td>忽略</td><td>强调未尽责任</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>over</em>（在上）+ <em>look</em>（看）</li><li><strong>Family:</strong> overlook 俯瞰；忽视 / look over 检查（语序颠倒，意思不同） / oversight 疏忽</li><li><strong>Memory Tip:</strong> 一个词两个方向：站在高处往下看是&quot;俯瞰&quot;（The hotel overlooks the sea）；该看没看见是&quot;忽视&quot;（overlook a detail）。中间夹个宾语就变成 look over（检查）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>表&quot;俯瞰&quot;时及物：The room overlooks the garden，不加 <s>to</s>。</li><li>表&quot;忽视&quot;含无意遗漏，故意不理要用 ignore。</li><li>oversight 是名词&quot;疏忽&quot;，也是&quot;监管&quot;，看语境判断。</li></ul></div><div class="vocab-card"><h2 id="flat" tabindex="-1"><a class="header-anchor" href="#flat"><span>Flat</span></a></h2><p class="vc-meta"><strong>/flæt/</strong> · adj · 形容词 / noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：平的，平坦的；平淡的；（电池）没电的；（轮胎）瘪的</li><li>名词：（英式）公寓，一套住房；平地</li><li>动词：使变平</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>flat land</td><td>平坦的土地</td></tr><tr><td>a flat tyre</td><td>瘪了的轮胎</td></tr><tr><td>flat surface</td><td>平面</td></tr><tr><td>a flat rate</td><td>统一费率</td></tr><tr><td>fall flat</td><td>（笑话、计划）失败</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The cross-section shows a flat plain extending east of the river.</p><blockquote><p>该剖面图显示河流以东延伸着一片平坦的平原。</p></blockquote><p><strong>Writing Task 2</strong> Flat terrain makes irrigation cheap, but it also leaves land vulnerable to flooding.</p><blockquote><p>平坦的地形使灌溉成本很低，但也让土地容易受洪涝影响。</p></blockquote><p><strong>Speaking</strong> The battery&#39;s flat — can I borrow your charger?</p><blockquote><p>电池没电了，能借你的充电器吗？</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>level</td><td>水平的</td><td>与水平面齐平，强调高度一致</td></tr><tr><td>even</td><td>平整的</td><td>强调没有凹凸</td></tr><tr><td>smooth</td><td>光滑的</td><td>强调触感细腻</td></tr><tr><td>plain</td><td>平原</td><td>名词，指地貌类型</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古诺斯语 <em>flatr</em>（平）</li><li><strong>Family:</strong> flat 平的；公寓 / flatten 使变平 / flattish 略平的 / flatly 断然地</li><li><strong>Memory Tip:</strong> 英式 flat 是&quot;一套公寓&quot;，美式说 apartment。所有引申义都从&quot;没起伏&quot;来：轮胎没气（瘪）、笑话没效果（flat）、语气没起伏（flatly）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式 flat（公寓）与美式 apartment 别混用在同一篇里。</li><li>flat 与 level 有别：flat 指无起伏，level 指与水平面齐平。</li><li>&quot;爆胎&quot;是 a flat tyre，不是 <s>a broken tyre</s>。</li></ul></div><div class="vocab-card"><h2 id="smooth" tabindex="-1"><a class="header-anchor" href="#smooth"><span>Smooth</span></a></h2><p class="vc-meta"><strong>/smuːð/</strong> · adj · 形容词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：光滑的，平整的；（进展）顺利的；（曲线）平滑的</li><li>动词：使平整；使顺利进行（smooth over）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a smooth surface</td><td>光滑的表面</td></tr><tr><td>a smooth trend</td><td>平滑的趋势</td></tr><tr><td>run smoothly</td><td>顺利进行</td></tr><tr><td>smooth over</td><td>缓和，平息</td></tr><tr><td>a smooth transition</td><td>平稳过渡</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The graph shows a smooth upward trend with no sharp fluctuations.</p><blockquote><p>该图显示出一条平滑上行的趋势，没有剧烈波动。</p></blockquote><p><strong>Writing Task 2</strong> The transition from coal to gas was smoother in some regions than in others.</p><blockquote><p>从煤到天然气的转型，在一些地区比其他地区更为平稳。</p></blockquote><p><strong>Speaking</strong> The road was so smooth that I fell asleep in the back seat.</p><blockquote><p>路太平顺了，我在后座睡着了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>even</td><td>平整的</td><td>强调无凹凸，不强调触感</td></tr><tr><td>sleek</td><td>光洁的</td><td>带光泽感，多形容外观设计</td></tr><tr><td>steady</td><td>平稳的</td><td>强调持续不变</td></tr><tr><td>polished</td><td>抛光的</td><td>强调人工打磨</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>smōth</em></li><li><strong>Family:</strong> smooth 光滑的 / smoothly 顺利地 / smoothness 平滑 / smoothie 果昔</li><li><strong>Memory Tip:</strong> 图表题里&quot;曲线平滑无剧烈波动&quot;就用 smooth——比 stable 更贴切，因为它同时描述形状与走势。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写中间是 oo、结尾 -th，别写成 <s>smoth</s>。</li><li>副词要加 -ly：run smoothly，不用 <s>run smooth</s>（美式口语偶见）。</li><li>形容路面&quot;平整&quot;可用 smooth / even，形容&quot;摩擦小&quot;只用 smooth。</li></ul></div><div class="vocab-card"><h2 id="rough" tabindex="-1"><a class="header-anchor" href="#rough"><span>Rough</span></a></h2><p class="vc-meta"><strong>/rʌf/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>粗糙的，不平的；崎岖的</li><li>粗略的，大致的</li><li>（海面）风浪大的；（言行）粗暴的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>rough surface</td><td>粗糙的表面</td></tr><tr><td>rough terrain</td><td>崎岖的地形</td></tr><tr><td>a rough estimate</td><td>粗略估计</td></tr><tr><td>rough sea</td><td>风浪大的海面</td></tr><tr><td>a rough draft</td><td>初稿</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a rough track connecting the two villages.</p><blockquote><p>该地图显示一条连接两个村子的崎岖小路。</p></blockquote><p><strong>Writing Task 2</strong> A rough estimate suggests the scheme will cost twice the original budget.</p><blockquote><p>粗略估计，该方案的花费将是原预算的两倍。</p></blockquote><p><strong>Speaking</strong> We had a rough crossing — half the passengers were sick.</p><blockquote><p>这趟渡海很颠簸，一半乘客都吐了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>coarse</td><td>粗糙的</td><td>强调颗粒粗，多形容质地</td></tr><tr><td>uneven</td><td>不平的</td><td>强调高低不平</td></tr><tr><td>approximate</td><td>粗略的</td><td>只对应&quot;估计&quot;义</td></tr><tr><td>harsh</td><td>严酷的</td><td>形容条件、气候</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>rūh</em>（粗糙、多毛）</li><li><strong>Family:</strong> rough 粗糙的 / roughly 大约；粗暴地 / roughness 粗糙 / roughen 使变粗糙</li><li><strong>Memory Tip:</strong> roughly 有两个高频义：&quot;大约&quot;（roughly 30 people）和&quot;粗暴地&quot;。图表题里 roughly 表&quot;约&quot;，几乎必考。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>roughly ≈ approximately，不要与 nearly（几乎）混。</li><li>&quot;风浪大&quot;是 rough sea，不用 <s>big sea</s>。</li><li>地形崎岖用 rough terrain，比 <s>rough land</s> 地道。</li></ul></div><div class="vocab-card"><h2 id="sandy" tabindex="-1"><a class="header-anchor" href="#sandy"><span>Sandy</span></a></h2><p class="vc-meta"><strong>/ˈsændi/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>沙质的，多沙的</li><li>沙色的（头发）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>sandy beach</td><td>沙滩</td></tr><tr><td>sandy soil</td><td>沙质土壤</td></tr><tr><td>sandy desert</td><td>沙质荒漠</td></tr><tr><td>sandy colour</td><td>沙色</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows that sandy soils dominate the coastal strip.</p><blockquote><p>该地图显示沿海一带以沙质土壤为主。</p></blockquote><p><strong>Writing Task 2</strong> Sandy soils drain quickly, so they need frequent irrigation and hold few nutrients.</p><blockquote><p>沙质土壤排水快，因此需要频繁灌溉，且养分含量很低。</p></blockquote><p><strong>Speaking</strong> We walked for hours over sandy ground, and my shoes are still full of it.</p><blockquote><p>我们在沙地上走了好几个小时，鞋里现在还有沙。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>gritty</td><td>含砂的</td><td>强调颗粒感，多形容触感</td></tr><tr><td>granular</td><td>颗粒状的</td><td>中性描述结构</td></tr><tr><td>arenaceous</td><td>沙质的</td><td>地质学术语，极书面</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>sand</em>（沙）+ <em>-y</em>（充满……的）</li><li><strong>Family:</strong> sand 沙 / sandy 沙质的 / sandstone 砂岩 / sand dune 沙丘</li><li><strong>Memory Tip:</strong> -y 后缀表示&quot;充满&quot;：sandy 多沙、stony 多石、rocky 多岩、muddy 多泥。地图题里这四个词一连串用得上。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>sandy 是形容词，&quot;沙质土壤&quot;是 sandy soil，不是 <s>sand soil</s>。</li><li>&quot;沙丘&quot;是 sand dune，不用 <s>sandy dune</s>。</li><li>发音 /ˈsændi/，注意别读成 /ˈsænd/。</li></ul></div><div class="vocab-card"><h2 id="stony" tabindex="-1"><a class="header-anchor" href="#stony"><span>Stony</span></a></h2><p class="vc-meta"><strong>/ˈstəʊni/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>多石的，石质的</li><li>冷冰冰的，面无表情的（stony silence）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>stony ground</td><td>多石的地面</td></tr><tr><td>stony beach</td><td>石滩</td></tr><tr><td>stony silence</td><td>死一般的沉默</td></tr><tr><td>stony-faced</td><td>面无表情的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The photograph shows stony ground with very little vegetation.</p><blockquote><p>照片显示一片几乎寸草不生的多石地面。</p></blockquote><p><strong>Writing Task 2</strong> Stony soils hold little water, which sharply limits what can be grown there.</p><blockquote><p>多石的土壤几乎存不住水，极大地限制了当地可种植的作物。</p></blockquote><p><strong>Speaking</strong> It was a stony path, and my ankles were aching by the end.</p><blockquote><p>那是条碎石小路，走到最后脚踝都疼了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rocky</td><td>多岩的</td><td>指大块岩石多，规模更大</td></tr><tr><td>pebbly</td><td>多卵石的</td><td>特指圆滑小石</td></tr><tr><td>barren</td><td>贫瘠的</td><td>强调无法生长植物</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>stone</em>（石）+ <em>-y</em></li><li><strong>Family:</strong> stone 石头 / stony 多石的 / stony silence 冷场 / stonework 石作</li><li><strong>Memory Tip:</strong> stony 与 rocky 分工清楚：stony 是&quot;小石块多、地面难走&quot;，rocky 是&quot;大岩块多、地形崎岖&quot;。stony silence 是&quot;死寂般的沉默&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>比较级 stonier，最高级 stoniest。</li><li>不能把名词 stone 直接当形容词用：<s>a stone ground</s> ✘ → stony ground。</li><li>stony-faced 是&quot;面无表情&quot;，不是&quot;石头脸&quot;。</li></ul></div><div class="vocab-card"><h2 id="vertical" tabindex="-1"><a class="header-anchor" href="#vertical"><span>Vertical</span></a></h2><p class="vc-meta"><strong>/ˈvɜːtɪkl/</strong> · adj · 形容词 / noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：垂直的，竖直的</li><li>名词：垂直线，竖直方向（the vertical）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the vertical axis</td><td>纵轴</td></tr><tr><td>a vertical cliff</td><td>垂直的崖壁</td></tr><tr><td>a vertical drop</td><td>垂直落差</td></tr><tr><td>a vertical line</td><td>垂直线</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The vertical axis shows population in thousands, while the horizontal axis shows years.</p><blockquote><p>纵轴以千人为单位显示人口，横轴显示年份。</p></blockquote><p><strong>Writing Task 2</strong> Vertical farming could cut transport costs in dense cities, though its energy demand is high.</p><blockquote><p>垂直农业可以降低密集城市的运输成本，尽管其能耗很高。</p></blockquote><p><strong>Speaking</strong> The climb is almost vertical at the top — you need both hands.</p><blockquote><p>顶部那段几乎是垂直的，得手脚并用。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>upright</td><td>竖直的</td><td>形容姿态直立，非几何</td></tr><tr><td>perpendicular</td><td>垂直的</td><td>几何学，指成直角</td></tr><tr><td>steep</td><td>陡峭的</td><td>形容坡度大，不一定是 90°</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>vertex</em>（顶点）→ <em>verticalis</em>，原义&quot;头顶正上方的&quot;</li><li><strong>Family:</strong> vertical 垂直的 / vertex 顶点 / vertically 垂直地 / vertigo 眩晕</li><li><strong>Memory Tip:</strong> vertex = 头顶的顶点。从天顶直上直下就是 vertical。几何上严格&quot;垂直（成直角）&quot;用 perpendicular。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 ver-ti-cal，别写成 <s>verticle</s>。</li><li>图表题固定说 the vertical axis，与 the horizontal axis 成对。</li><li>steep 是&quot;陡&quot;，vertical 是&quot;直&quot;，别把陡坡说成 vertical。</li></ul></div><div class="vocab-card"><h2 id="steep" tabindex="-1"><a class="header-anchor" href="#steep"><span>Steep</span></a></h2><p class="vc-meta"><strong>/stiːp/</strong> · adj · 形容词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：陡的，陡峭的；（上升或下降）急剧的；（价格）过高的</li><li>动词：浸泡（茶叶等）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a steep slope</td><td>陡坡</td></tr><tr><td>a steep cliff</td><td>陡崖</td></tr><tr><td>a steep rise in prices</td><td>价格急剧上涨</td></tr><tr><td>a steep learning curve</td><td>陡峭的学习曲线</td></tr><tr><td>steeply</td><td>陡峭地</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The profile shows a steep drop of 200 metres over just one kilometre.</p><blockquote><p>该剖面图显示在一公里内陡降了两百米。</p></blockquote><p><strong>Writing Task 2</strong> A steep rise in housing costs has pushed young families out of the city centre.</p><blockquote><p>住房成本的急剧上涨把年轻家庭挤出了市中心。</p></blockquote><p><strong>Speaking</strong> The last part of the trail is really steep — take your time.</p><blockquote><p>最后一段路很陡，慢慢走。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>sheer</td><td>陡直的</td><td>强调几乎垂直，多形容崖壁</td></tr><tr><td>precipitous</td><td>险峻的</td><td>书面，带危险意味</td></tr><tr><td>abrupt</td><td>突然的</td><td>只对应&quot;急剧变化&quot;义</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>stēap</em>（高、陡）</li><li><strong>Family:</strong> steep 陡的 / steeply 陡峭地 / steepen 变得更陡 / steepness 陡度</li><li><strong>Memory Tip:</strong> 两条线都好用：地形陡（a steep slope）、价格涨得猛（a steep rise）。steep learning curve 指&quot;上手极难&quot;。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>&quot;陡坡&quot;是 a steep slope；路本身用 steep road 也可以，但严格说陡的是坡度。</li><li>副词是 steeply：prices rose steeply。</li><li>别与 step（台阶、步骤）混，拼写只差一个 e。</li></ul></div><div class="vocab-card"><h2 id="parallel" tabindex="-1"><a class="header-anchor" href="#parallel"><span>Parallel</span></a></h2><p class="vc-meta"><strong>/ˈpærəlel/</strong> · adj · 形容词 / noun · 名词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：平行的；类似的，对应的</li><li>名词：平行线；相似之处</li><li>动词：与……相似；与……同时进行</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>parallel lines</td><td>平行线</td></tr><tr><td>run parallel to</td><td>与……平行</td></tr><tr><td>in parallel with</td><td>与……同时进行</td></tr><tr><td>draw a parallel between</td><td>指出……之间的相似</td></tr><tr><td>parallel universe</td><td>平行宇宙</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The two roads run parallel to the river for about five kilometres.</p><blockquote><p>这两条路与河流平行延伸约五公里。</p></blockquote><p><strong>Writing Task 2</strong> There are clear parallels between coastal erosion here and on the Atlantic seaboard.</p><blockquote><p>这里的海岸侵蚀与大西洋沿岸的情况有明显相似之处。</p></blockquote><p><strong>Speaking</strong> My career has run parallel to my brother&#39;s, though neither of us planned it.</p><blockquote><p>我的职业轨迹和我哥哥的很相似，虽然我们俩都没计划过。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>analogous</td><td>类似的</td><td>强调可类比，学术用</td></tr><tr><td>comparable</td><td>可比的</td><td>强调程度、规模相当</td></tr><tr><td>alongside</td><td>与……并排</td><td>副词/介词，非形容词</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 希腊 <em>para-</em>（旁边）+ <em>allelos</em>（彼此）→ <em>parallelos</em></li><li><strong>Family:</strong> parallel 平行的 / parallelism 平行结构 / unparalleled 无与伦比的</li><li><strong>Memory Tip:</strong> para-（旁）+ allelos（彼此）= 一条挨着另一条。unparalleled 就是&quot;没有能与之并排的&quot;，即无与伦比。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>介词用 parallel to 或 parallel with，两者都对。</li><li>英式拼写结尾双 l（parallel），别写成 <s>paralel</s>。</li><li>&quot;指出相似之处&quot;用 draw a parallel between A and B。</li></ul></div><div class="vocab-card"><h2 id="narrow" tabindex="-1"><a class="header-anchor" href="#narrow"><span>Narrow</span></a></h2><p class="vc-meta"><strong>/ˈnærəʊ/</strong> · adj · 形容词 / verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>形容词：窄的，狭窄的；（差距）微小的；狭隘的</li><li>动词：使变窄；缩小（范围）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>a narrow street</td><td>狭窄的街道</td></tr><tr><td>a narrow valley</td><td>狭窄的河谷</td></tr><tr><td>a narrow margin</td><td>微弱差距</td></tr><tr><td>narrow down</td><td>缩小范围</td></tr><tr><td>narrow-minded</td><td>心胸狭隘的</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a narrow strip of farmland between the road and the river.</p><blockquote><p>该地图显示公路与河流之间有一条狭长的农田带。</p></blockquote><p><strong>Writing Task 2</strong> The vote was won by a narrow margin, so the policy remains contested.</p><blockquote><p>该议案以微弱优势通过，因此这项政策仍存争议。</p></blockquote><p><strong>Speaking</strong> The streets in the old town are so narrow that two cars can&#39;t pass.</p><blockquote><p>老城区的街道太窄，两辆车都错不开。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>slim</td><td>细的</td><td>多形容身材、机会</td></tr><tr><td>tight</td><td>紧的</td><td>强调空间受限、贴得紧</td></tr><tr><td>confined</td><td>有限的</td><td>书面，强调受限制</td></tr><tr><td>limited</td><td>有限的</td><td>泛用，指数量或范围</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 古英语 <em>nearu</em>（狭窄、紧迫）</li><li><strong>Family:</strong> narrow 窄的 / narrowly 勉强地；仔细地 / narrowness 狭窄 / narrow-minded 狭隘的</li><li><strong>Memory Tip:</strong> 三个高频搭配一次记：a narrow margin（微弱差距）、narrow down（缩小范围）、narrow-minded（心胸狭隘）。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>动词可及物：narrow the gap（缩小差距）。</li><li>副词 narrowly 常表&quot;勉强&quot;：narrowly escaped（险些没逃掉）。</li><li>反义词是 wide，不是 <s>broadly</s>（后者是副词）。</li></ul></div><div class="vocab-card"><h2 id="oceania" tabindex="-1"><a class="header-anchor" href="#oceania"><span>Oceania</span></a></h2><p class="vc-meta"><strong>/ˌəʊsiˈɑːniə/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>大洋洲（太平洋岛屿与澳新的统称）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the islands of Oceania</td><td>大洋洲诸岛</td></tr><tr><td>across Oceania</td><td>遍及大洋洲</td></tr><tr><td>Oceania and Asia</td><td>大洋洲与亚洲</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows the island groups that together make up Oceania.</p><blockquote><p>该地图显示了共同构成大洋洲的各个岛群。</p></blockquote><p><strong>Writing Task 2</strong> Oceania consists of thousands of islands scattered across a fifth of the Pacific.</p><blockquote><p>大洋洲由散布在太平洋五分之一海域的数千座岛屿组成。</p></blockquote><p><strong>Speaking</strong> I&#39;ve always wanted to island-hop around Oceania, but the flights are expensive.</p><blockquote><p>我一直想在大洋洲跳岛旅行，但机票太贵了。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>the Pacific islands</td><td>太平洋岛屿</td><td>口语化，不含澳新</td></tr><tr><td>Australasia</td><td>澳大拉西亚</td><td>仅指澳大利亚、新西兰及邻近岛</td></tr><tr><td>the South Pacific</td><td>南太平洋</td><td>偏海域，非大洲概念</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>oceanus</em>（海洋）+ <em>-ia</em>（地区）→ &quot;海洋组成的区域&quot;，1831 年由法国地理学家划分</li><li><strong>Family:</strong> Oceania 大洋洲 / Oceanian 大洋洲的 / ocean 海洋 / oceanic 海洋的</li><li><strong>Memory Tip:</strong> ocean + -ia 字面就是&quot;海洋之地&quot;。它不是一个大陆，主体是撒在太平洋上的岛屿，所以要与 Australia（澳大利亚大陆）分开理解。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 Oce-ania，注意中间是 -ce-。</li><li>Oceania ≠ Australia：澳洲只是其中的一部分。</li><li>首字母大写；作地理区域一般不加 the。</li></ul></div><div class="vocab-card"><h2 id="mainland" tabindex="-1"><a class="header-anchor" href="#mainland"><span>Mainland</span></a></h2><p class="vc-meta"><strong>/ˈmeɪnlənd/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>大陆，本土（相对岛屿、离岛而言）</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the mainland</td><td>大陆，本土</td></tr><tr><td>mainland China</td><td>中国大陆</td></tr><tr><td>mainland Europe</td><td>欧洲大陆</td></tr><tr><td>on the mainland</td><td>在大陆／本土</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows ferry routes connecting the island to the mainland.</p><blockquote><p>该地图显示了连接该岛与大陆的轮渡航线。</p></blockquote><p><strong>Writing Task 2</strong> Young people leave the islands for the mainland in search of work and education.</p><blockquote><p>年轻人离开岛屿前往本土，寻求工作与教育机会。</p></blockquote><p><strong>Speaking</strong> The ferry to the mainland only runs twice a day in winter.</p><blockquote><p>冬天开往大陆的轮渡一天只有两班。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>continent</td><td>大陆，洲</td><td>按板块划分，规模最大</td></tr><tr><td>the interior</td><td>内陆</td><td>强调距海远，不涉及岛屿</td></tr><tr><td>home country</td><td>本国</td><td>国籍视角，非地理</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>main</em>（主要的）+ <em>land</em>（陆地）</li><li><strong>Family:</strong> mainland 本土 / mainlander 本土居民 / mainline 主干线</li><li><strong>Memory Tip:</strong> main + land = &quot;主要的那块陆地&quot;。它的参照物是&quot;岛&quot;——站在岛上，对岸就是 mainland。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>加冠词：the mainland。</li><li>mainland China 前不加 the。</li><li>与 continent 不同：mainland 是相对岛屿的说法，continent 是地质板块概念。</li></ul></div><div class="vocab-card"><h2 id="peninsula" tabindex="-1"><a class="header-anchor" href="#peninsula"><span>Peninsula</span></a></h2><p class="vc-meta"><strong>/pəˈnɪnsjələ/</strong> · noun · 名词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>半岛</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>the Iberian Peninsula</td><td>伊比利亚半岛</td></tr><tr><td>a narrow peninsula</td><td>狭长的半岛</td></tr><tr><td>on the peninsula</td><td>在半岛上</td></tr><tr><td>the Antarctic Peninsula</td><td>南极半岛</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows a narrow peninsula extending south into the sea.</p><blockquote><p>该地图显示一条向南伸入海中的狭长半岛。</p></blockquote><p><strong>Writing Task 2</strong> Coastal peninsulas are exposed to storm surges on three sides, making them hard to defend.</p><blockquote><p>沿海半岛三面临海，易受风暴潮侵袭，防御困难。</p></blockquote><p><strong>Speaking</strong> We stayed on a little peninsula — there was water on both sides of the house.</p><blockquote><p>我们住在一个小半岛上，房子两边都是水。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>cape</td><td>海角</td><td>更小，仅尖端突出部分</td></tr><tr><td>headland</td><td>岬角</td><td>高起的突出陆地</td></tr><tr><td>spit</td><td>沙嘴</td><td>沙质细长堆积体</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>paene</em>（几乎）+ <em>insula</em>（岛）→ &quot;几乎是一个岛&quot;</li><li><strong>Family:</strong> peninsula 半岛 / insular 岛屿的；保守的 / isolate 隔离 / island 岛</li><li><strong>Memory Tip:</strong> paene（几乎）+ insula（岛）= 三面环水、一面连着陆地——&quot;差不多是个岛&quot;。同根词 insula 还长出了 island、isolate。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>拼写 pen-in-sula，中间是 insula，别写成 <s>peninsular</s>（那是形容词）。</li><li>地名首字母大写：the Iberian Peninsula。</li><li>与 cape（海角）区分：半岛是一整块伸出的陆地，海角只是尖端。</li></ul></div><div class="vocab-card"><h2 id="fertile" tabindex="-1"><a class="header-anchor" href="#fertile"><span>Fertile</span></a></h2><p class="vc-meta"><strong>/ˈfɜːtaɪl/</strong> · adj · 形容词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>肥沃的，富饶的</li><li>能生育的</li><li>（想象力）丰富的</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>fertile soil</td><td>肥沃的土壤</td></tr><tr><td>fertile land</td><td>肥沃的土地</td></tr><tr><td>the Fertile Crescent</td><td>新月沃地</td></tr><tr><td>a fertile imagination</td><td>丰富的想象力</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The map shows fertile soils concentrated along the river valley.</p><blockquote><p>该地图显示了集中在河谷沿线的肥沃土壤。</p></blockquote><p><strong>Writing Task 2</strong> River floods deposit silt that keeps delta soils fertile year after year.</p><blockquote><p>河流洪水带来的淤泥使三角洲土壤年复一年保持肥沃。</p></blockquote><p><strong>Speaking</strong> The soil here is incredibly fertile — everything grows.</p><blockquote><p>这里的土极其肥沃，种什么都长。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>rich</td><td>富饶的</td><td>口语，形容土壤、资源</td></tr><tr><td>productive</td><td>高产的</td><td>强调产出能力</td></tr><tr><td>fruitful</td><td>有成果的</td><td>多用于讨论、合作</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> 拉丁 <em>fertilis</em> ← <em>ferre</em>（带来、出产）</li><li><strong>Family:</strong> fertile 肥沃的 / fertility 肥力；生育力 / fertilise 施肥 / fertilizer 肥料</li><li><strong>Memory Tip:</strong> ferre = 带来（同 transfer、refer）。能&quot;带来出产&quot;的地就是肥沃的。Fertile Crescent（新月沃地）是文明起源话题的经典表述。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>名词是 fertility（肥力、生育力）。</li><li>fertilise 是动词&quot;施肥&quot;，fertilizer 是&quot;肥料&quot;。</li><li>拼写 fer-tile，别写成 <s>fertal</s>。</li></ul></div><div class="vocab-card"><h2 id="fertilise" tabindex="-1"><a class="header-anchor" href="#fertilise"><span>Fertilise</span></a></h2><p class="vc-meta"><strong>/ˈfɜːtəlaɪz/</strong> · verb · 动词</p><p class="vc-label"><strong>核心释义（Definitions）</strong></p><ul><li>给……施肥，使肥沃</li><li>使受精</li></ul><p class="vc-label"><strong>核心搭配（Collocations）</strong></p><table class="table-fill"><thead><tr><th>搭配</th><th>中文释义</th></tr></thead><tbody><tr><td>fertilise the soil</td><td>给土壤施肥</td></tr><tr><td>fertilise crops</td><td>给作物施肥</td></tr><tr><td>over-fertilise</td><td>过度施肥</td></tr><tr><td>artificially fertilise</td><td>人工授精</td></tr></tbody></table><p class="vc-label"><strong>例句（Examples）</strong></p><p><strong>Writing Task 1</strong> The diagram shows how farmers fertilise fields with nitrogen.</p><blockquote><p>该示意图显示了农民如何用氮肥给田地施肥。</p></blockquote><p><strong>Writing Task 2</strong> Over-fertilising farmland sends nutrients into rivers, where they trigger algal blooms.</p><blockquote><p>农田过度施肥使养分流入河流，引发藻华。</p></blockquote><p><strong>Speaking</strong> We fertilise the garden twice a year, in spring and autumn.</p><blockquote><p>我们一年给园子施两次肥，春天一次秋天一次。</p></blockquote><p class="vc-label"><strong>同义替换（Synonyms）</strong></p><table class="table-fill"><thead><tr><th>词汇</th><th>中文释义</th><th>使用区别</th></tr></thead><tbody><tr><td>feed</td><td>供给养分</td><td>口语，也可指喂养</td></tr><tr><td>enrich</td><td>使肥沃</td><td>强调提高养分含量</td></tr><tr><td>treat</td><td>处理</td><td>泛指，需上下文说明</td></tr></tbody></table><p class="vc-label"><strong>词根与记忆（Word Formation）</strong></p><ul><li><strong>Root:</strong> <em>fertile</em>（肥沃的）+ <em>-ise</em>（使……）</li><li><strong>Family:</strong> fertilise 施肥 / fertilizer 肥料 / fertilisation 施肥；受精 / fertility 肥力</li><li><strong>Memory Tip:</strong> -ise 是英式拼写（美式 -ize），表&quot;使……&quot;。注意名词 fertilizer（肥料）几乎总用 -izer 形式，英式也如此。</li></ul><p class="vc-label"><strong>常见错误（Common Mistakes）</strong></p><ul><li>英式 fertilise、美式 fertilize，同一篇文章里保持一致。</li><li>名词&quot;肥料&quot;是 fertilizer（英式也可写 fertiliser），全篇统一即可。</li><li>over-fertilise 带连字符。</li></ul></div>`,26)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};